mapper.select:
SELECT c.*,i.id invCaseId,o.id orgCaseId FROM survey_clock_case c LEFT JOIN survey_user_clock u ON c.clock_id = u.id LEFT JOIN survey_investigator_case i ON c.survey_info_id = i.survey_info_id AND u.survey_user_id = i.survey_user_id AND i.delete_flag = 0 LEFT JOIN survey_assign_org o ON u.survey_org_id = o.survey_org_id AND c.survey_info_id = o.survey_info_id AND o.delete_flag = 0 WHERE c.clock_id = #{id}
AND c.entrust_type = 2
AND c.entrust_type = 1
